import type {
  ActionHeaderProps,
  ActionHeaderLeadingProps,
  ActionHeaderCenterProps,
  ActionHeaderTrailingProps,
  ActionHeaderDividerProps,
  ActionHeaderStatusProps,
} from "./action-header.types";

import { Children, cloneElement, isValidElement, forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Divider } from "@components/divider";
import { IconButton, type IconButtonProps } from "@components/icon-button";
import { Menu } from "@exp-textura/icons";

import { StyledActionHeader, ActionHeaderClasses } from "./action-header.styles";

const recursiveCloneChildren = (children: React.ReactNode): React.ReactNode => {
  return Children.map(children, (child) => {
    if (!isValidElement(child)) {
      return child;
    }

    const displayName = (child.type as { displayName?: string }).displayName;
    const sizeToApply = "sm";

    if (
      (displayName === "Button" ||
        displayName === "IconButton" ||
        displayName === "ToggleButton") &&
      !child.props.size
    ) {
      return cloneElement(child, {
        size: sizeToApply,
        buttonType:
          displayName === "IconButton"
            ? child.props.buttonType || "secondary"
            : child.props.buttonType,
      });
    }

    if (child.props.children) {
      const clonedChildren = recursiveCloneChildren(child.props.children);
      return cloneElement(child, { children: clonedChildren });
    }

    return child;
  });
};

const ActionHeaderRoot = forwardRef<HTMLDivElement, ActionHeaderProps>(
  ({ className, variant = "default", children, ...props }, ref) => {
    const theme = useTheme();
    const rootClasses = clsx(ActionHeaderClasses.root, className);

    return (
      <StyledActionHeader
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledActionHeader>
    );
  },
);
ActionHeaderRoot.displayName = "ActionHeader";

const ActionHeaderLeading = forwardRef<HTMLDivElement, ActionHeaderLeadingProps>(
  ({ className, children, ...props }, ref) => {
    const childrenWithProps = recursiveCloneChildren(children);

    return (
      <div ref={ref} className={clsx(ActionHeaderClasses.leading, className)} {...props}>
        {childrenWithProps}
      </div>
    );
  },
);
ActionHeaderLeading.displayName = "ActionHeader.Leading";

const ActionHeaderCenter = forwardRef<HTMLDivElement, ActionHeaderCenterProps>(
  ({ className, children, ...props }, ref) => {
    const childrenWithProps = recursiveCloneChildren(children);

    return (
      <div ref={ref} className={clsx(ActionHeaderClasses.center, className)} {...props}>
        {childrenWithProps}
      </div>
    );
  },
);
ActionHeaderCenter.displayName = "ActionHeader.Center";

const ActionHeaderTrailing = forwardRef<HTMLDivElement, ActionHeaderTrailingProps>(
  ({ className, children, ...props }, ref) => {
    const childrenWithProps = recursiveCloneChildren(children);

    return (
      <div ref={ref} className={clsx(ActionHeaderClasses.trailing, className)} {...props}>
        {childrenWithProps}
      </div>
    );
  },
);
ActionHeaderTrailing.displayName = "ActionHeader.Trailing";

const ActionHeaderDivider = forwardRef<HTMLDivElement, ActionHeaderDividerProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(ActionHeaderClasses.divider, className)} {...props}>
        {children ?? <Divider orientation="vertical" size="sm" />}
      </div>
    );
  },
);
ActionHeaderDivider.displayName = "ActionHeader.Divider";

const ActionHeaderStatus = forwardRef<HTMLSpanElement, ActionHeaderStatusProps>(
  ({ className, ...props }, ref) => {
    return <span ref={ref} className={clsx(ActionHeaderClasses.status, className)} {...props} />;
  },
);
ActionHeaderStatus.displayName = "ActionHeader.Status";

const ActionHeaderMenuIconButton = forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ size = "sm", children, ...props }, ref) => {
    return (
      <IconButton ref={ref} buttonType="secondary" size={size} {...props}>
        {children || <Menu />}
      </IconButton>
    );
  },
);
ActionHeaderMenuIconButton.displayName = "ActionHeader.MenuIconButton";

const ActionHeader = Object.assign(ActionHeaderRoot, {
  Leading: ActionHeaderLeading,
  Center: ActionHeaderCenter,
  Trailing: ActionHeaderTrailing,
  Divider: ActionHeaderDivider,
  Status: ActionHeaderStatus,
  MenuIconButton: ActionHeaderMenuIconButton,
});

export default ActionHeader;
